import { Button, HeaderBar } from '@/components'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { getBlurhashFromUUID } from '@/utils/getBlurhashFromUUID'
import { useMe } from '@/utils/hooks/useMe'
import BottomSheet from '@gorhom/bottom-sheet'
import { Image } from 'expo-image'
import { router } from 'expo-router'
import { Trash2 } from 'lucide-react-native'
import { useRef, useState } from 'react'
import { Text, View } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { DeleteAccountBottomSheet } from './components/DeleteAccountBottomSheet'
import { useLogout } from '@/utils/hooks/useLogout'

export const DeleteAccountScreen = () => {
	const { me } = useMe()
	const insets = useSafeAreaInsets()
	const { theme } = useTheme()
	const bottomSheetRef = useRef<BottomSheet>(null)
	const [sliderKey, setSliderKey] = useState(0)
	const { handleLogout } = useLogout()

	const onClose = () => {
		router.back()
	}

	const handleOpenDeleteBottomSheet = () => {
		setSliderKey((prev) => prev + 1)
		bottomSheetRef.current?.snapToIndex(0)
	}

	return (
		<>
			<View
				style={[
					styles.container(theme),
					{ paddingTop: insets.top, paddingBottom: insets.bottom + 16 }
				]}
			>
				<HeaderBar title="Delete account" onClose={onClose} />

				<View style={styles.contentContainer}>
					<View style={styles.headerContainer}>
						<View style={styles.profileImageContainer}>
							<Image
								source={me?.profile?.photoURL ?? null}
								style={styles.profileImage}
								placeholder={{ blurhash: getBlurhashFromUUID(me?.id ?? '') }}
							/>
							<View style={styles.deleteSymbol(theme)}>
								<Trash2 size={20} color={colors.dark.gray[900]} />
							</View>
						</View>

						<Text style={styles.displayName(theme)}>{me?.displayName}</Text>
					</View>

					<View style={styles.actionContainer}>
						<View style={styles.deleteAccountDescription}>
							<Text style={styles.deleteAccountDescriptionTitle(theme)}>
								If you delete this account:
							</Text>
							<Text style={styles.deleteAccountDescriptionText(theme)}>
								If you delete this account, all apps associated with this
								account will be deleted.{'\n'}You will not be able to log back
								in with this account.
							</Text>
						</View>

						<Button
							text="Delete account"
							variant="destructive"
							onPress={handleOpenDeleteBottomSheet}
						/>
					</View>
				</View>
			</View>
			<DeleteAccountBottomSheet
				sliderKey={sliderKey}
				bottomSheetRef={bottomSheetRef}
				handleLogout={handleLogout}
			/>
		</>
	)
}

const styles = defineStyles({
	container: (theme: Theme) => ({
		flex: 1,
		backgroundColor: colors[theme].background,
		gap: 20,
		paddingHorizontal: 24
	}),
	contentContainer: {
		gap: 32
	},
	headerContainer: {
		gap: 16
	},
	profileImageContainer: {
		alignSelf: 'center',
		marginBottom: 14
	},
	profileImage: {
		width: 72,
		height: 72,
		borderRadius: 100
	},
	deleteSymbol: (theme: Theme) => ({
		position: 'absolute',
		right: -14,
		bottom: -14,
		borderWidth: 2,
		borderColor: colors[theme].background,
		backgroundColor: colors[theme].red[300],
		borderRadius: 100,
		padding: 12
	}),
	displayName: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900],
		textAlign: 'center'
	}),
	actionContainer: {
		gap: 24
	},
	deleteAccountDescription: {
		gap: 16
	},
	deleteAccountDescriptionTitle: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900]
	}),
	deleteAccountDescriptionText: (theme: Theme) => ({
		fontSize: 16,
		color: colors[theme].gray[400],
		lineHeight: 20
	})
})
